var D = {"activities": {"outside": [{"title": "Regarder, vraiment.", "body": "Sors ou installe-toi près d’une fenêtre. Téléphone posé, remarque trois détails que tu n’avais jamais vus : une couleur, une forme, un mouvement.", "prompt": "Décris un de ces détails comme si tu voulais le faire découvrir à quelqu’un qui n’était pas là.", "tip": "Tu n’as pas besoin d’aller loin. Un endroit familier peut devenir une découverte."}, {"title": "Écouter ce qui est là.", "body": "Dans un lieu où tu peux rester en sécurité, écoute les sons autour de toi. Repère un son proche, un son lointain et les silences entre les deux.", "prompt": "Décris le lieu en utilisant uniquement ce que tu as entendu.", "tip": "Essaie ce moment sans écouteurs, si cela te convient."}, {"title": "Un lieu, un souvenir.", "body": "Observe un lieu ou un objet dehors. Laisse venir un souvenir ou une association d’idées, sans chercher à vérifier quoi que ce soit sur ton téléphone.", "prompt": "Commence par « Cet endroit me rappelle… » et poursuis avec tes propres mots.", "tip": "Le souvenir peut être minuscule. Il n’a pas besoin d’être extraordinaire."}, {"title": "Changer de point de vue.", "body": "Choisis une petite promenade adaptée à tes possibilités, ou change simplement de place. Observe comment un même endroit semble différent depuis ce nouveau point de vue.", "prompt": "Qu’as-tu découvert en changeant de place ? Décris un avant et un après.", "tip": "Choisis un trajet connu et sûr. Adapte la distance à ton énergie."}, {"title": "Ramener une idée.", "body": "Cherche dehors une couleur, une texture ou une forme qui t’inspire. Garde-la en mémoire pour en faire ensuite un dessin ou quelques lignes sur papier.", "prompt": "Dessine ton détail de mémoire, puis écris une phrase pour l’accompagner.", "tip": "Pas besoin de photo ni de modèle. Ton interprétation suffit."}, {"title": "Un moment à deux.", "body": "Propose à une personne de marcher, de regarder dehors ou de discuter avec les téléphones rangés. Si tu préfères rester seul, observe un lieu où les gens se rencontrent.", "prompt": "Quelle phrase ou quel détail de ce moment aimerais-tu conserver ?", "tip": "Partager est une invitation. Tu peux choisir de rester seul."}, {"title": "Ce que tu veux garder.", "body": "Reprends le moment dehors que tu as préféré dans ce parcours. Choisis un endroit et une durée qui te conviennent aujourd’hui.", "prompt": "Complète : « J’aimerais garder cette habitude parce que… »", "tip": "Une habitude tenable peut être toute petite. Choisis-la pour toi."}], "creative": [{"title": "Dessiner sans modèle.", "body": "Choisis un objet près de toi. Observe-le, puis dessine-le sur papier sans ouvrir une image de référence. Accueille les imperfections.", "prompt": "Qu’as-tu remarqué en dessinant que tu n’avais pas vu au premier regard ?", "tip": "Un stylo et une feuille suffisent. Le résultat n’a pas à être joli."}, {"title": "Un son, une histoire.", "body": "Écoute un son autour de toi. Sur papier, invente une scène très courte dans laquelle ce son apparaît. Laisse les idées venir sans rechercher d’inspiration en ligne.", "prompt": "Commence par « J’ai entendu… » et écris la suite.", "tip": "Trois phrases peuvent déjà raconter quelque chose."}, {"title": "Une page à toi.", "body": "Prends une feuille. Écris ce qui te traverse l’esprit aujourd’hui, sans correction et sans chercher un sujet parfait. Tu peux aussi commencer par décrire ce qui t’entoure.", "prompt": "« En ce moment, je remarque… » Puis laisse ton écriture continuer.", "tip": "Tu peux t’arrêter après quelques lignes. Rien n’est noté ni évalué."}, {"title": "Une pause entre les idées.", "body": "Pose ton matériel et change doucement de position, ou marche un peu si tu le peux. Puis reviens à ta feuille et observe si une autre idée est apparue.", "prompt": "Note une idée venue pendant cette pause, même incomplète.", "tip": "Le mouvement est une possibilité, pas une obligation."}, {"title": "Trois façons d’imaginer.", "body": "Choisis un objet banal et imagine trois usages inattendus. Note-les ou dessine-les sur papier avant toute recherche et sans aide de l’IA.", "prompt": "Quelle idée te surprend le plus ? Développe-la en quelques lignes.", "tip": "Autorise-toi les idées étranges : c’est un exercice, pas un concours."}, {"title": "Créer pour quelqu’un.", "body": "Écris quelques mots ou fais un petit dessin destiné à quelqu’un. Tu peux lui offrir en personne, ou le garder pour toi.", "prompt": "Quel détail personnel as-tu choisi pour cette personne ?", "tip": "Tu n’as aucune obligation de publier ou d’envoyer ta création."}, {"title": "Garder ton élan.", "body": "Reprends une activité créative appréciée dans ce parcours. Installe ton matériel, pose le téléphone et choisis une petite réalisation possible aujourd’hui.", "prompt": "Quelle place aimerais-tu donner à cette activité dans ta semaine ?", "tip": "Laisse une feuille et un crayon accessibles pour la prochaine fois."}], "movement": [{"title": "Changer de position.", "body": "Quitte quelques instants ta position habituelle. Installe-toi autrement ou lève-toi si cela te convient. Repère ce qui paraît confortable, sans chercher une posture parfaite.", "prompt": "Qu’est-ce qui a changé dans ton ressenti après cette pause ?", "tip": "Bouge dans une amplitude confortable. Une douleur est un signal pour arrêter."}, {"title": "Une promenade attentive.", "body": "Marche à ton rythme si tu le peux, dans un endroit sûr. Tu peux aussi faire une pause assise dans un autre lieu. Écoute les sons sans regarder ton téléphone.", "prompt": "Décris un son qui t’a accompagné pendant ce moment.", "tip": "Adapte la proposition à tes possibilités, même sans sortir."}, {"title": "Du corps aux mots.", "body": "Après une courte pause ou un changement de position, prends une feuille. Décris ton énergie et ton confort avec des mots simples, sans chercher de diagnostic.", "prompt": "« Aujourd’hui, je me sens… » Écris ce qui te semble juste.", "tip": "Ton ressenti n’a pas à être positif. Il peut simplement être différent."}, {"title": "Une mobilité toute douce.", "body": "Assieds-toi de façon confortable, pieds soutenus. Si cela ne provoque aucune douleur, tourne lentement la tête d’un côté puis de l’autre, dans une petite amplitude. Reviens au centre. Tu peux préférer marcher ou changer de position.", "prompt": "Quel mouvement ou quelle position t’a semblé le plus confortable ?", "tip": "Exercice inspiré du NHS : sans forcer, sans douleur. En cas de douleur persistante, demande un avis professionnel."}, {"title": "Dessiner le mouvement.", "body": "Après un mouvement confortable ou une petite marche, dessine sur papier les lignes qui évoquent ton ressenti. Tu peux aussi rester assis et dessiner le mouvement observé dehors.", "prompt": "Ajoute trois mots à ton dessin pour décrire ton expérience.", "tip": "Quelques traits suffisent. Tu n’as rien à prouver."}, {"title": "Une pause ensemble.", "body": "Invite quelqu’un à faire une pause sans téléphone : marcher, changer d’air ou discuter. Si tu préfères, garde ce moment pour toi.", "prompt": "Qu’as-tu apprécié ou moins apprécié pendant ce moment ?", "tip": "Chacun adapte l’activité à son énergie et à ses possibilités."}, {"title": "Ta pause, à ta façon.", "body": "Reprends la pause ou le mouvement qui t’a convenu. Choisis un moment réaliste pour le refaire dans les prochains jours.", "prompt": "Quel petit changement pourrait rendre tes journées plus confortables ?", "tip": "Varier les positions et ajuster son poste peut aider au confort. Aucune posture n’est à maintenir toute la journée."}]}, "days": ["Observer", "Écouter", "Écrire", "Bouger", "Créer", "Partager", "Choisir"], "themes": [{"id": "outside", "label": "Prendre l’air", "description": "Observer, écouter, découvrir"}, {"id": "creative", "label": "Créer quelque chose", "description": "Écrire, dessiner, imaginer"}, {"id": "movement", "label": "Me remettre en mouvement", "description": "Marcher, varier mes positions"}]};
