var CH = {"habits": [{"id": "social", "label": "Réseaux sociaux"}, {"id": "video", "label": "Vidéos courtes en boucle"}, {"id": "news", "label": "Actualités en continu"}, {"id": "games", "label": "Jeux sur mobile"}, {"id": "stream", "label": "Séries et streaming en boucle"}, {"id": "bed", "label": "Téléphone au lit"}, {"id": "notifs", "label": "Notifications non essentielles"}], "evidence": {"etabli": "Bien établi", "observe": "Observé dans des études", "hypothese": "Hypothèse plausible"}, "challenges": [{"id": "soiree", "title": "Soirée sans écran", "tagline": "Un soir pour souffler, sans engagement.", "duration": "Environ 3 heures", "level": "Facile", "tone": "lilac", "icon": "moon", "intro": "Le meilleur point de départ : ce soir, les écrans de loisir restent de côté et tu observes ce que ça change.", "prep": ["Choisis l’heure de départ et un endroit où ranger ton téléphone, hors de vue.", "Prépare une activité papier : un livre, un carnet, un jeu de cartes.", "Prévois une exception pour les vraies urgences (un appel reste possible)."], "defaultHabits": ["social", "video", "stream", "bed"], "paliers": [{"at": 0, "when": "Tout de suite", "title": "Je range le téléphone", "do": "Mets-le dans une autre pièce ou un tiroir. Dis-toi à voix haute : « ce soir, il reste là ».", "brain": "À force de répétitions, ton cerveau a appris que sortir le téléphone apporte une petite récompense rapide, et la main part toute seule. Décider à l’avance (« ce soir, il reste là ») fonctionne mieux que de se retenir à chaque fois.", "evidence": "etabli", "source": "Les plans « si… alors… » aident à tenir un objectif (méta-analyse de Gollwitzer et Sheeran, 2006).", "invite": {"theme": "outside", "day": 0}, "hy": "Active « Ne pas déranger » et pose le téléphone écran vers le bas, à plus d’un bras de toi."}, {"at": 1, "when": "Après 1 heure", "title": "L’envie va et vient", "do": "Quand l’envie de checker arrive, nomme-la dans ta tête (« tiens, une envie »), puis reprends ce que tu faisais.", "brain": "Dans les études où l’on retire le smartphone pendant 24 heures, c’est surtout l’envie de le reprendre qui augmente, pas forcément l’anxiété ni la mauvaise humeur. Une envie fonctionne souvent par vagues : elle monte, puis redescend si on ne la suit pas.", "evidence": "observe", "source": "Université de Lancaster, 2019 (revue Addictive Behaviors) : 24 h sans smartphone.", "hy": "Si tu dois le prendre (appel, minuteur), fais-le, puis repose-le sans ouvrir autre chose."}, {"at": 2, "when": "Après 2 heures", "title": "Le temps ralentit", "do": "Fais une chose lente : cuisiner, dessiner, ranger, lire quelques pages.", "brain": "Quand les temps morts ne sont plus comblés par un écran, l’esprit se met à vagabonder : souvenirs, idées, projets. Certaines personnes y trouvent du calme, d’autres de l’ennui au début. Les deux sont normaux, et l’ennui ne veut pas dire que ça ne marche pas.", "evidence": "hypothese", "invite": {"theme": "creative", "day": 2}, "hy": "Musique ou podcast autorisés, écran éteint, pour accompagner une activité lente."}, {"at": 3, "when": "Après 3 heures", "title": "Cap sur la nuit", "do": "Garde le téléphone hors de la chambre, ou au moins loin du lit. Utilise un vrai réveil.", "brain": "Un écran allumé au lit garde souvent l’esprit en alerte (fils d’actualité, messages), ce qui peut retarder l’endormissement. Dans une étude d’une semaine avec moins de réseaux sociaux, les symptômes d’insomnie ont baissé de 14,5 % en moyenne, avec de grandes différences d’une personne à l’autre.", "evidence": "observe", "source": "JAMA Network Open, novembre 2025 : 295 jeunes adultes, une semaine de réseaux sociaux réduits, sans groupe témoin.", "hy": "Garde-le pour le réveil seulement, branché loin du lit, en « Ne pas déranger »."}], "hybrid": {"intro": "Le téléphone reste là, mais en retrait : tu ne t’en sers que pour l’utile.", "rules": ["« Ne pas déranger » activé jusqu’à demain matin, avec tes proches en exception.", "Écran vers le bas, hors de portée de main.", "Autorisé : appels, musique, minuteur, carte si besoin.", "En pause : réseaux sociaux, vidéos courtes, actualités."]}}, {"id": "weekend", "title": "Aventure d’un week-end", "tagline": "48 heures pour ressentir la différence.", "duration": "48 heures", "level": "Moyen", "tone": "mint", "icon": "mountain", "intro": "Du départ au retour, tu mets de côté tes habitudes d’écran pendant tout un week-end. À chaque palier, tu découvres ce que ton cerveau peut ressentir.", "prep": ["Préviens tes proches que tu seras moins réactif·ve.", "Prévois trois activités hors écran : une dehors, une créative, une pour bouger.", "Installe un vrai réveil et une horloge ou une montre.", "Garde ce qui est utile : télécharge ou imprime à l’avance un itinéraire ou des billets."], "defaultHabits": ["social", "video", "news", "games", "stream", "bed"], "paliers": [{"at": 0, "when": "Au départ", "title": "Décollage", "do": "Choisis ton heure de départ, mets le téléphone en mode avion ou dans un tiroir, et note sur papier ce que tu veux faire ce week-end.", "brain": "Les décisions prises à l’avance sont plus faciles à tenir. Avoir des activités prêtes évite que le vide soit rempli par le réflexe d’écran.", "evidence": "etabli", "source": "Les plans « si… alors… » aident à tenir un objectif (méta-analyse de Gollwitzer et Sheeran, 2006).", "invite": {"theme": "outside", "day": 0}, "hy": "Choisis tes exceptions (proches, appels) et laisse « Ne pas déranger » faire le tri."}, {"at": 3, "when": "Après 3 heures", "title": "Le réflexe fantôme", "do": "Si ta main va chercher la poche ou si tu sens une vibration qui n’existe pas, c’est normal. Souris et continue.", "brain": "Les gestes répétés des centaines de fois se déclenchent tout seuls dans les contextes familiers (canapé, transports, attente). Beaucoup de gens décrivent même de fausses vibrations. Dans une petite étude de 41 étudiants, la séparation d’avec leur téléphone faisait monter l’anxiété et le rythme cardiaque ; sur 24 heures entières, l’étude de Lancaster n’a vu monter que l’envie. Les résultats ne vont pas tous dans le même sens.", "evidence": "observe", "source": "Université de Lancaster, 2019 (revue Addictive Behaviors) : 24 h sans smartphone.", "hy": "Si l’envie de checker arrive, attends ta fenêtre prévue plutôt que de céder tout de suite."}, {"at": 12, "when": "Après 12 heures", "title": "La première nuit", "do": "Couche-toi sans écran, avec un livre ou une musique douce. Prévois un vrai réveil pour le matin.", "brain": "Sans fil d’actualité ni messages au lit, l’esprit a moins de choses à traiter avant de dormir. Plusieurs études associent moins de réseaux sociaux à un meilleur sommeil, surtout chez des personnes qui dormaient mal. Une seule nuit ne change pas tout : vois-la comme un essai.", "evidence": "observe", "source": "JAMA Network Open, novembre 2025 : 295 jeunes adultes, une semaine de réseaux sociaux réduits, sans groupe témoin.", "hy": "Téléphone hors de la chambre ; un réveil classique si tu en as un, sinon une alarme et rien d’autre."}, {"at": 24, "when": "Après 24 heures", "title": "Un jour entier", "do": "Fais la grande activité du week-end : balade, sortie, projet manuel, repas avec quelqu’un.", "brain": "À ce stade, ce que les études mesurent surtout, c’est l’envie de reprendre le téléphone. Sur 24 heures, l’humeur et l’anxiété n’avaient pas bougé en moyenne. Si tu te sens un peu agité·e, ça arrive et ça passe souvent avec l’activité. Si c’est très inconfortable, tu peux arrêter sans te juger.", "evidence": "observe", "source": "Université de Lancaster, 2019 (revue Addictive Behaviors) : 24 h sans smartphone.", "invite": {"theme": "outside", "day": 3}, "hy": "Garde cartes et appareil photo pour la sortie, mais pas les réseaux : tu publies plus tard, ou jamais."}, {"at": 36, "when": "Après 36 heures", "title": "L’attention se pose", "do": "Essaie une activité longue sans interruption : lire 20 pages, un puzzle, une vraie conversation.", "brain": "Beaucoup de gens racontent qu’ils tiennent plus longtemps sur une même chose quand le téléphone n’est plus là. Les mesures d’attention en laboratoire montrent des effets après deux semaines, pas après un week-end : ici, c’est un avant-goût, pas une preuve.", "evidence": "hypothese", "invite": {"theme": "creative", "day": 0}, "hy": "Lis, écris ou dessine avec le téléphone en mode avion pendant l’activité."}, {"at": 48, "when": "Au retour", "title": "Retour en douceur", "do": "Reprends en deux temps : d’abord un seul usage utile, notifications éteintes pour le reste. Note ce que tu n’as pas manqué.", "brain": "Dans l’essai de deux semaines, le temps d’écran est remonté après la fin du blocage, sans retrouver tout à fait son niveau de départ. Reprendre avec des règles claires aide à garder une partie du bénéfice.", "evidence": "observe", "source": "PNAS Nexus, 2025 : essai randomisé de 2 semaines sans internet mobile, 467 adultes.", "hy": "Reprends par une seule fenêtre de 15 minutes pour tes messages, puis décide de tes règles."}], "hybrid": {"intro": "Tu gardes l’utile et tu limites le reste à de courtes fenêtres.", "rules": ["« Ne pas déranger » du début à la fin du week-end, avec tes proches en exception.", "Deux fenêtres de 15 minutes par jour pour les messages.", "Autorisé : appels, cartes, musique, photos (sans publier).", "En pause : réseaux sociaux, vidéos courtes, jeux, actualités."]}}, {"id": "semaine", "title": "Semaine reset", "tagline": "7 jours pour desserrer le réflexe.", "duration": "7 jours", "level": "Moyen", "tone": "sky", "icon": "calendar", "intro": "Une semaine pour changer tes routines : moins de scroll, plus de sommeil, plus de présence. Un format qui a été testé dans des études.", "prep": ["Coupe les notifications non essentielles et sors les applis tentantes de l’écran d’accueil.", "Charge ton téléphone hors de la chambre.", "Repère tes moments-réflexe (matin au lit, transports, attente) et prépare une alternative.", "Prévois un moment avec quelqu’un en vrai, dans la semaine."], "defaultHabits": ["social", "video", "news", "notifs", "bed"], "paliers": [{"at": 0, "when": "Jour 1", "title": "Je mets en place", "do": "Coupe les notifications non essentielles, cache les applis tentantes et charge le téléphone hors de la chambre.", "brain": "Rendre le réflexe un peu plus difficile (une appli cachée, un téléphone dans une autre pièce) réduit les usages automatiques : tu gagnes une seconde pour décider.", "evidence": "observe", "hy": "Fixe tes trois fenêtres (matin, midi, soir) et coupe tout le reste."}, {"at": 24, "when": "Jour 2", "title": "Les temps morts", "do": "Quand tu attends (file, transport), regarde autour de toi ou prends un livre.", "brain": "Les temps morts sont souvent comblés sans y penser. Les retirer laisse un vide au début, qui se remplit de pensées, d’observations, parfois d’ennui. C’est le signe que le réflexe se desserre, pas que tu fais fausse route.", "evidence": "hypothese", "invite": {"theme": "outside", "day": 0}, "hy": "Pendant un temps mort, écoute quelque chose hors ligne plutôt que de scroller."}, {"at": 72, "when": "Jour 4", "title": "Le sommeil", "do": "Fixe une heure de coucher sans écran et note sur papier comment tu t’endors.", "brain": "Après quelques jours, certaines personnes s’endorment plus vite et dorment mieux. Dans des études où l’on réduit les réseaux sociaux (de 1 à 3 semaines), les symptômes d’insomnie ou le temps de sommeil se sont améliorés en moyenne, mais les résultats varient beaucoup selon les personnes.", "evidence": "observe", "source": "JAMA Network Open, novembre 2025 : 295 jeunes adultes, une semaine de réseaux sociaux réduits, sans groupe témoin.", "hy": "Fixe une heure à la dernière fenêtre du soir, puis téléphone hors de la chambre."}, {"at": 120, "when": "Jour 6", "title": "L’humeur", "do": "Écris trois mots sur ton humeur du jour, sur papier, puis appelle ou retrouve quelqu’un en vrai.", "brain": "Dans un essai randomisé d’une semaine sans réseaux sociaux, le bien-être et l’anxiété se sont améliorés, et la dépression aussi chez les personnes qui avaient déjà des symptômes. Ce sont des moyennes : certaines personnes ne ressentent presque rien, et c’est normal.", "evidence": "observe", "source": "Essai randomisé d’une semaine sans réseaux sociaux, 154 adultes (Cyberpsychology, Behavior and Social Networking, 2022).", "invite": {"theme": "outside", "day": 5}, "hy": "Réserve ton quota de réseaux à une fenêtre, et note ton humeur avant et après."}, {"at": 168, "when": "Jour 7", "title": "Le bilan", "do": "Regarde ce que tu as gagné (temps, sommeil, humeur) et choisis une ou deux règles à garder.", "brain": "Une semaine suffit pour sentir une différence chez beaucoup de gens, mais les études suggèrent que les bénéfices sont plus nets à partir de 10 jours à 2 semaines. Tu peux enchaîner avec la détox complète si l’envie est là.", "evidence": "observe", "source": "PNAS Nexus, 2025 : essai randomisé de 2 semaines sans internet mobile, 467 adultes.", "hy": "Compte les jours où tu as respecté tes fenêtres, sans chercher la perfection."}], "hybrid": {"intro": "Trois fenêtres par jour pour tout le reste : c’est le rythme testé dans les études sur les notifications.", "rules": ["Notifications coupées, sauf appels et messages de tes proches.", "Trois fenêtres par jour (matin, midi, soir) pour le reste.", "Téléphone hors de la chambre la nuit.", "Réseaux sociaux : environ 30 minutes par jour au plus, pendant une fenêtre."]}}, {"id": "complete", "title": "Détox complète", "tagline": "30 jours pour changer de rythme pour de bon.", "duration": "30 jours", "level": "Ambitieux", "tone": "pink", "icon": "star", "intro": "Le grand défi : un mois pour remplacer tes réflexes d’écran par d’autres habitudes. Tu gardes ce qui est utile (appels, travail, banque, cartes) et tu mets le reste de côté.", "prep": ["Liste ce qui est vraiment utile et que tu gardes : appels, messages importants, banque, cartes, travail.", "Supprime ou bloque les applis tentantes, ou demande à un proche de les verrouiller.", "Prépare un carnet et trois activités hors écran que tu aimes.", "Parle de ton défi à une personne qui peut te soutenir."], "defaultHabits": ["social", "video", "news", "games", "stream", "bed", "notifs"], "paliers": [{"at": 0, "when": "Jour 1", "title": "Le grand tri", "do": "Choisis ce que tu mets en pause, bloque ou supprime les applis tentantes, et garde seulement l’utile.", "brain": "En psychologie, les récompenses imprévisibles sont celles qui accrochent le plus, et beaucoup de fils d’actualité fonctionnent ainsi (« et s’il y avait du nouveau ? »). C’est un mécanisme plausible, pas la preuve que tout le monde est « accro ». Retirer ces sources t’aide à voir ce qui reste quand elles disparaissent.", "evidence": "hypothese", "hy": "Applis tentantes supprimées ou bloquées ; tes essentiels (travail, banque, cartes) restent installés."}, {"at": 72, "when": "3 jours", "title": "Le plus dur est souvent là", "do": "Si l’envie est forte, marche cinq minutes ou bois un verre d’eau, puis décide.", "brain": "Les premiers jours, l’envie de checker est la plus présente : le réflexe cherche son signal. Il n’existe pas de « seuil magique » prouvé à 3 jours, mais beaucoup de personnes disent que ça s’allège ensuite.", "evidence": "hypothese", "invite": {"theme": "movement", "day": 1}, "hy": "Ouvre une fenêtre si besoin, mais pas avant : l’envie passe souvent pendant ces cinq minutes."}, {"at": 168, "when": "1 semaine", "title": "Un peu moins d’anxiété ?", "do": "Note ce qui a changé : sommeil, humeur, concentration. Écris-le sur papier.", "brain": "Dans une étude de 2025 où 295 jeunes adultes ont réduit leurs réseaux sociaux pendant 7 jours, l’anxiété a baissé de 16 % en moyenne, la dépression de 25 % et l’insomnie de 14,5 %. Les écarts entre personnes étaient grands, et il n’y avait pas de groupe témoin.", "evidence": "observe", "source": "JAMA Network Open, novembre 2025 : 295 jeunes adultes, une semaine de réseaux sociaux réduits, sans groupe témoin.", "hy": "Note ce qui change quand tu limites ton téléphone à deux fenêtres par jour."}, {"at": 240, "when": "10 jours", "title": "Le seuil des études", "do": "Fais une sortie sans téléphone, ou propose un moment à deux sans écran.", "brain": "Dans l’essai de deux semaines sans internet mobile, les personnes qui ont tenu au moins 10 jours ont eu les meilleures améliorations de santé mentale et de bien-être, et un peu moins nettes sur l’attention. Tu entres dans la zone où les effets mesurés deviennent plus clairs.", "evidence": "observe", "source": "PNAS Nexus, 2025 : essai randomisé de 2 semaines sans internet mobile, 467 adultes.", "invite": {"theme": "outside", "day": 5}, "hy": "Sors avec le téléphone en mode avion ou « Ne pas déranger », et regarde-le seulement pour un vrai besoin."}, {"at": 336, "when": "2 semaines", "title": "L’attention", "do": "Choisis un projet qui demande de la concentration : lire un chapitre, dessiner, apprendre quelque chose.", "brain": "C’est la durée de l’essai de 467 adultes : l’attention soutenue s’est améliorée d’un niveau comparable à environ 10 ans de déclin lié à l’âge, et environ 7 personnes sur 10 ont vu leur santé mentale progresser. Ces personnes passaient aussi plus de temps avec les autres, dehors et à bouger. Attention : cette étude bloquait tout internet mobile, ton défi est plus souple, tes résultats peuvent différer.", "evidence": "observe", "source": "PNAS Nexus, 2025 : essai randomisé de 2 semaines sans internet mobile, 467 adultes.", "invite": {"theme": "creative", "day": 4}, "hy": "Bloque des plages de concentration (téléphone en retrait) plutôt qu’une coupure totale."}, {"at": 504, "when": "3 semaines", "title": "Le mythe des 21 jours", "do": "Si tu as flanché un jour, reprends simplement le lendemain. Un jour raté n’efface pas le reste.", "brain": "On lit partout qu’il faut 21 jours pour créer une habitude. Dans une étude de 2010, il fallait en moyenne environ 66 jours, avec de 18 à 254 jours selon les personnes. Si tu n’y es pas encore, ce n’est pas un manque de volonté : c’est du temps.", "evidence": "observe", "source": "Lally et coll., 2010 : 96 personnes suivies pour installer une nouvelle habitude.", "hy": "Un écart ne compte pas : reprends tes fenêtres au prochain créneau."}, {"at": 720, "when": "30 jours", "title": "Ton nouveau rythme", "do": "Choisis deux ou trois règles durables : téléphone hors de la chambre, un jour par semaine sans réseaux, notifications coupées.", "brain": "À 30 jours, tu n’as pas « réinitialisé » ton cerveau : c’est une image, pas un résultat prouvé. Ce qui a changé, ce sont tes routines, tes signaux et peut-être ton sommeil et ton humeur. Les habitudes tiennent surtout grâce au contexte (lieu, moment) qui déclenche le geste : c’est lui qu’il faut garder aménagé.", "evidence": "etabli", "hy": "Garde deux ou trois règles (fenêtres, notifications coupées, téléphone hors de la chambre) : c’est ton rythme durable."}], "hybrid": {"intro": "Les applis tentantes disparaissent, mais tes outils du quotidien restent.", "rules": ["Réseaux, vidéos courtes, jeux et actualités en pause pendant tout le mois (applis supprimées ou bloquées).", "Gardés : appels, messages utiles, cartes, banque, travail, santé.", "Deux ou trois fenêtres par jour pour les messages non urgents.", "Un jour de souplesse par semaine si besoin, sans culpabilité."]}}], "science": {"title": "Ce que la science dit, et ne dit pas", "points": ["Les effets décrits sont des moyennes : certaines personnes se sentent nettement mieux, d’autres peu.", "Beaucoup d’études sont courtes, petites ou sans groupe témoin. Ce sont des pistes, pas des garanties.", "« Reset de dopamine » ou « cerveau réparé en 48 h » sont des images populaires, pas des résultats prouvés.", "Tout ou rien n’est pas obligatoire : le mode hybride (appels et utile gardés, fenêtres choisies) a aussi des appuis dans la recherche. Voir « Pourquoi l’hybride compte vraiment ».", "Un défi n’est pas un traitement. Si tes écrans te pèsent beaucoup, ou si tu te sens mal (anxiété forte, tristesse qui dure), parles-en à un·e médecin ou à un·e psychologue."]}};
