var HY = {"defaultMode": "hybrid", "modes": [{"id": "strict", "label": "Sans téléphone", "desc": "Le téléphone reste de côté pendant tes moments et tes défis."}, {"id": "hybrid", "label": "Hybride", "desc": "Tu gardes le téléphone pour l’utile et tu l’ouvres à des heures choisies."}], "essentials": [{"id": "calls", "label": "Appels et messages importants"}, {"id": "maps", "label": "Cartes et transports"}, {"id": "bank", "label": "Banque et paiement"}, {"id": "work", "label": "Travail"}, {"id": "health", "label": "Santé et urgences"}, {"id": "music", "label": "Musique et podcasts"}, {"id": "photo", "label": "Photos"}, {"id": "read", "label": "Lecture"}], "defaultEssentials": ["calls", "maps", "bank", "work", "health"], "defaultWindows": [{"start": "08:30", "end": "08:45"}, {"start": "12:30", "end": "12:45"}, {"start": "18:30", "end": "19:00"}], "maxWindows": 4, "why": {"title": "Pourquoi l’hybride compte vraiment", "points": ["Dans l’essai de deux semaines sans internet mobile (467 adultes, PNAS Nexus, 2025), les participants gardaient appels et SMS. Ceux qui n’ont pas tout respecté ont quand même progressé, un peu moins.", "Dans un essai de 237 personnes (Computers in Human Behavior, 2019), recevoir ses notifications en trois groupes par jour a réduit le stress et amélioré l’humeur, et les participants déverrouillaient moins leur téléphone. Les grouper chaque heure n’apportait presque rien.", "Dans la même étude, couper totalement les notifications a augmenté l’anxiété et la peur de rater quelque chose : une coupure complète n’est pas toujours la meilleure solution.", "D’où deux à trois fenêtres par jour plutôt qu’une coupure totale. Les résultats varient selon les personnes : l’hybride n’est pas une version au rabais, c’est une façon de tenir dans la vraie vie."]}, "away": {"strict": {"title": ["Tu peux poser", "ton téléphone."], "note": ""}, "hybrid": {"title": ["Mets ton téléphone", "en retrait."], "note": "Mode avion ou « Ne pas déranger », écran vers le bas, hors de portée de main. Tu peux t’en servir pour un essentiel, puis le reposer."}}, "mapStep": {"strict": {"t": "Pars", "d": "Sans ton téléphone, ou éteint au fond du sac."}, "hybrid": {"t": "Pars", "d": "Téléphone en mode avion : carte et urgences seulement."}}, "mapNote": {"strict": "Le lien ouvre une vraie carte, centrée sur ta position si ton appareil l’autorise. Repère un lieu, note son nom sur papier, puis pars.", "hybrid": "Mode hybride : garde ton téléphone pour t’orienter. Ouvre la carte, repère ton chemin, puis passe-le en mode avion pendant ta sortie."}};
var TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;
function toMin(t) { var p = t.split(':'); return Number(p[0]) * 60 + Number(p[1]); }
function validWindows(list) {
  return Array.isArray(list) && list.length <= HY.maxWindows && list.every(function (w) { return w && TIME_RE.test(w.start) && TIME_RE.test(w.end) && toMin(w.end) > toMin(w.start); });
}
/* Fenêtre ouverte, prochaine fenêtre (aujourd'hui ou demain) ou aucune fenêtre. */
function windowStatus(now, wins) {
  if (!wins.length) return { kind: 'none' };
  var m = now.getHours() * 60 + now.getMinutes();
  var sorted = wins.slice().sort(function (a, b) { return toMin(a.start) - toMin(b.start); });
  for (var i = 0; i < sorted.length; i++) if (m >= toMin(sorted[i].start) && m < toMin(sorted[i].end)) return { kind: 'open', end: sorted[i].end, left: toMin(sorted[i].end) - m };
  for (var j = 0; j < sorted.length; j++) if (toMin(sorted[j].start) > m) return { kind: 'next', start: sorted[j].start, inMin: toMin(sorted[j].start) - m, tomorrow: false };
  return { kind: 'next', start: sorted[0].start, inMin: 24 * 60 - m + toMin(sorted[0].start), tomorrow: true };
}
function fmtMin(n) { if (n < 60) return n + ' min'; var h = Math.floor(n / 60), r = n % 60; return h + ' h' + (r ? ' ' + String(r).padStart(2, '0') : ''); }
function essLabels(ids) { return ids.map(function (id) { var e = HY.essentials.find(function (x) { return x.id === id; }); return e ? e.label : null; }).filter(Boolean); }
function chById(id) { return chList.find(function (c) { return c.id === id; }); }

