/* Textes légaux : remplis avec les valeurs de config.js. */
function fillLegal(s) { return String(s).replace(/\{\{(\w+)\}\}/g, function (m, k) { var v = PUB[k]; return v ? v : (k === 'dpo' ? '' : '[à compléter]'); }); }
