  if (!r || !b) return;
  var to = { tab: S.tab, x: b.offsetLeft, y: b.offsetTop, w: b.offsetWidth, h: b.offsetHeight };
  var from = !instant && ribbonPrev && ribbonPrev.tab !== S.tab ? ribbonPrev : null;
